//! Finite child selection and projections compatible with unchanged RootLaunch3.
//! No provider/signer API is exposed here; B performs exact prepared custody.
use crate::{Result,need,sha,policy::{self,Policy,Pin,Plan,Recipe,text,array,DECISION},pe,pipe::Channel,job::Job};
use serde_json::{Value,json};use std::{path::Path,collections::BTreeSet};
fn selected<'a>(p:&'a Option<String>,why:&str)->Result<&'a str>{p.as_deref().ok_or_else(||why.into())}
pub(crate) struct Selection{pe:pe::Capsule,source:String,provider:String,proof:Vec<u8>,results:Vec<u8>,own:String,comparator:u32}
impl Selection{
 pub(crate) fn admit(p:&Policy,startup:&Value)->Result<Self>{let r=&p.recipe;let own=selected(&r.child_image,"actual separately admitted child image required")?;let capture_path=selected(&r.child_capture_path,"actual full compiled child capture required")?;let provider_path=selected(&r.provider_manifest_path,"selected provider manifest required")?;let proof_path=selected(&r.child_abi_path,"actual child same-source ABI required")?;let results_path=selected(&r.child_abi_results_path,"actual child same-source ABI results required")?;
  let capture=p.record(capture_path)?;policy::complete_capture(&capture)?;let source=sha(p.bytes(capture_path)?);let m=p.record(provider_path)?;let provider=sha(p.bytes(provider_path)?);need(m["source_verification_sha256"]==source&&m["runtime_eligible"]==false&&m["production_disabled"]==true,"separate provider manifest/source domains")?;for k in ["head","tree","source"]{need(m[k]==capture[k],"same source identity")?}let files=array(&m,"files",4096)?;let originals=array(&capture,"current_files",4096)?;need(files==originals&&array(&m,"locks",policy::CURRENT_CAPTURE_LOCK_COUNT)?==array(&capture,"locks",policy::CURRENT_CAPTURE_LOCK_COUNT)?,"exact complete source rows and current 17 lock rows")?;
  need((2..=512).contains(&r.child_objects.len()),"finite selected child native universe")?;let mut objects=Vec::new();let mut paths=BTreeSet::new();let mut total=0u64;for pin in &r.child_objects{need(paths.insert(pin.path.to_ascii_lowercase())&&((pin.path==own&&pin.object_class=="OwnTestImage"&&pin.links==1)||(pin.path!=own&&pin.object_class=="System32Dll")),"exact unique child native roles")?;total=total.checked_add(pin.bytes).ok_or("child PE byte overflow")?;need(total<=536870912,"whole child PE before allocation")?;objects.push(pe::parse(&pin.path,p.bytes(&pin.path)?)?)}let pe=pe::capsule(objects,own)?;let pin=r.child_objects.iter().find(|s|s.path==own).ok_or("actual child original")?;let app=p.record(selected(&r.child_admission_path,"actual APP admission required")?)?;
  need(app["scope"]=="ROOT_ADMITTED_NATIVE_OWNER_TEST_APPLICATION_ARTIFACT"&&app["compiled_source_sha256"]==source&&app["provider_source_manifest_sha256"]==provider&&app["path"]==pin.path&&app["sha256"]==pin.sha256&&app["bytes"]==pin.bytes&&app["volume"]==pin.volume&&app["file_id"]==pin.file_id&&app["links"]==1&&app["profile_test"]==false&&app["target_name"]=="mutiny-wallet-v8-testvalue"&&app["normal_shipping"]==false,"actual APP original/source/profile; old ABI harness is refused")?;policy::features(&app)?;policy::verify_abi(p,proof_path,results_path,&source,&pe)?;
  let context_path=selected(&r.application_context_path,"separately reviewed entire child context required")?;need(startup["application_context_sha256"]==sha(p.bytes(context_path)?),"Root-admitted exact entire child context commitment")?;boundary(p,&p.record(context_path)?,&source,&provider)?;
  Ok(Self{comparator:pe.comparator()?,pe,source,provider,proof:p.bytes(proof_path)?.to_vec(),results:p.bytes(results_path)?.to_vec(),own:own.into()})
 }
 fn rows(&self,r:&Recipe,paths:Option<&[String]>)->Vec<Value>{r.child_objects.iter().filter(|s|paths.is_none_or(|v|v.iter().any(|p|p==&s.path))).map(|p|serde_json::to_value(p).unwrap()).collect()}
 fn registration(&self,p:&Policy)->Result<Vec<u8>>{p.require()?;bounded(&json!({"scope":"AUTHENTICATED_ROOT_TEST1001_SELECTED_REGISTRATION","compiled_source_capture_sha256":self.source,"provider_source_manifest_sha256":self.provider,"campaign":p.recipe.campaign,"own_image":self.own,"comparator_direct_rva":self.comparator,"abi_proof_sha256":sha(&self.proof),"abi_results_sha256":sha(&self.results),"original_objects":self.rows(&p.recipe,None)}))}
 fn projection(&self,p:&Policy,child:&crate::own_native_token::OwnTokenFacts,paths:&[String])->Result<Vec<u8>>{p.require()?;crate::same_role(&p.token,child)?;let projected=self.pe.project(paths)?;let rows=self.rows(&p.recipe,Some(paths));need(rows.len()==paths.len(),"all selected actual child originals")?;let own=p.recipe.child_objects.iter().find(|s|s.path==self.own).ok_or("actual child original")?;
  bounded(&json!({"scope":"AUTHENTICATED_ROOT_TEST1001_LIVE_CHILD_SELECTION","compiled_source_capture_sha256":self.source,"provider_source_manifest_sha256":self.provider,"campaign":p.recipe.campaign,"own_image":self.own,"own_sha256":own.sha256,"comparator_direct_rva":self.comparator,"parent_image":p.own,"parent_image_sha256":p.own_pin()?.sha256,"parent_token":crate::token_json(&p.token),"child_token":crate::token_json(child),"original_objects":rows,"pe":projected,"abi_proof_bytes_hex":hex::encode(&self.proof),"abi_results_bytes_hex":hex::encode(&self.results)}))
 }
 pub(crate) fn exchange(&self,p:&Policy,c:&Channel,job:&Job)->Result<()>{let current=||{p.require()?;c.require_child(job)};c.connect(||{p.require()?;job.peer()?;Ok(())})?;current()?;need(c.read(&current)?==b"ROOT_REGISTRATION_REQUEST","one authenticated Root registration request")?;c.send("ROOT_CAPSULE_BYTES",&self.registration(p)?,&current)?;let mut paths=Vec::new();let mut seen=BTreeSet::new();let mut text=0usize;loop{let row=String::from_utf8(c.read(&current)?).map_err(|_|"actual child roster UTF8")?;if row=="ROOT_OWN_ROSTER_END"{break}let path=row.strip_prefix("ROOT_OWN_PATH ").ok_or("fixed complete child roster message")?;text=text.checked_add(path.len()).ok_or("child roster text overflow")?;need(paths.len()<512&&path.len()<=1006&&text<=262144&&seen.insert(path.to_ascii_lowercase()),"unique complete bounded actual child roster")?;paths.push(path.into())}let token=job.peer()?.0.clone();c.send("ROOT_CAPSULE_BYTES",&self.projection(p,&token,&paths)?,&current)?;need(c.read(&current)?==b"ROOT_LIVE_OWNER_ACCEPTED","actual child live owner acknowledged once; loss UNKNOWN")?;current()}
}
fn bounded(v:&Value)->Result<Vec<u8>>{crate::json_bytes(v,67108864)}
/// Port of source3's boundary: environment, cwd, output and complete plan are
/// committed independently, before any trusted child process is created.
fn boundary(p:&Policy,c:&Value,source:&str,provider:&str)->Result<()>{let r=&p.recipe;let plan=r.application.as_ref().ok_or("selected complete child plan")?;let own=selected(&r.child_image,"child image")?;let directory=Path::new(own).parent().ok_or("literal child image directory")?;need(c["scope"]=="ROOT_SELECTED_NATIVE_TEST_APPLICATION_CONTEXT_V5"&&c["decision_sha256"]==DECISION&&c["operation"]==r.operation&&c["campaign"]==r.campaign&&c["compiled_capture_sha256"]==source&&c["provider_manifest_sha256"]==provider&&c["admitted_application_sha256"]==sha(p.bytes(selected(&r.child_admission_path,"APP admission")?)?)&&c["admitted_abi_sha256"]==sha(p.bytes(selected(&r.child_abi_path,"ABI admission")?)?)&&c["application_plan_sha256"]==sha(&serde_json::to_vec(plan).map_err(|e|e.to_string())?),"exact independently selected entire effective plan/context")?;
 need(plan.schema=="SOURCE_OWNED_NATIVE_TEST_OWNER_ACTION_V5"&&plan.ordinary_sid==pipe_sid()&&plan.unresolved.is_empty()&&plan.inputs.len()==r.child_objects.len()&&(2..=512).contains(&plan.inputs.len()),"finite TEST action role/unresolved/membership")?;let mut seen=BTreeSet::new();for pin in &plan.inputs{need(seen.insert(pin.path.to_ascii_lowercase())&&r.child_objects.iter().any(|s|serde_json::to_value(s).ok()==serde_json::to_value(pin).ok()),"each exact selected retained child original")?}need(plan.absences.len()>=1&&plan.absences.len()<=128&&plan.absences.contains(&(own.to_owned()+".local")),"child redirect absence")?;let mut absent=BTreeSet::new();for path in &plan.absences{policy::strict(path)?;need(absent.insert(path.to_ascii_lowercase())&&r.absences.contains(path),"forwarded absence held by pre-entry originals")?}
 need(plan.action.image==own&&Path::new(&plan.action.working_directory)==directory&&plan.child_environment.len()==2&&plan.child_environment.get("SystemRoot").is_some_and(|s|s==r"C:\Windows")&&plan.child_environment.get("WINDIR").is_some_and(|s|s==r"C:\Windows"),"exact cleared child environment and original-image cwd")?;policy::strict(&plan.output_prefix)?;let out=Path::new(&plan.output_prefix);let operation=if r.operation=="TEST_PREPARE"{"prepare"}else{"reopen"};let prefix=format!("native-owner-{operation}-");let name=out.file_name().and_then(|s|s.to_str()).ok_or("child output name")?;need(out.parent()==Path::new(&p.own).parent()&&plan.output_prefix!=r.output_prefix&&name.starts_with(&prefix)&&name.len()==prefix.len()+32&&name[prefix.len()..].bytes().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase()),"finite fresh child capture namespace")?;
 let base=text(c,"provider_base_path")?;policy::strict(base)?;need(base.starts_with(r"C:\Users\admin\")&&Path::new(base).file_name().and_then(|s|s.to_str())==Some(format!("test-providers-{}",&r.campaign[..16]).as_str()),"exact independently Root-admitted protected C TEST custody namespace; G build location conveys no custody authority")?;for a in &plan.action.arguments{need(!a.is_empty()&&a.len()<=1024&&!a.contains('\0'),"literal finite TEST arguments")?}let a=&plan.action.arguments;
 if r.operation=="TEST_PREPARE"{need(plan.action.kind=="native-owner-test-prepare"&&a.len()==7&&a[0]=="--native-owner-test-prepare"&&a[1]==base&&a[2]==r.campaign&&a[3]==selected(&r.provider_manifest_path,"provider path")?&&a[4]==provider&&c.get("existing_receipt_path").is_some_and(Value::is_null)&&c.get("existing_receipt_sha256").is_some_and(Value::is_null),"exact new protected TEST prepare selectors")?;let capture=p.record(selected(&r.child_capture_path,"child capture")?)?;need(a[5]==text(&capture,"head")?,"actual compiled child source HEAD")?;let lifetime=a[6].parse::<u64>().map_err(|_|"selected TEST lifetime")?;need((1..=3600000).contains(&lifetime)&&a[6]==lifetime.to_string(),"canonical finite TEST lifetime")?
 }else{need(r.operation=="TEST_REOPEN"&&plan.action.kind=="native-owner-test-run"&&a.len()==3&&a[0]=="--native-owner-test-run"&&a[1]==format!("{base}\\native-owner-prepared.json")&&c["existing_receipt_path"]==a[1]&&c["existing_receipt_sha256"]==a[2],"fresh original same identity existing-only prepared receipt; no reset")?;policy::hexn::<32>(&a[2])?;}p.require()
}
fn pipe_sid()->&'static str{crate::pipe::sid_text()}
struct Launch{channel:Option<Channel>,job:Option<Job>}
pub(crate) fn run(p:&Policy,startup:&Value)->Result<Value>{
 let selected=Selection::admit(p,startup)?;let plan=p.recipe.application.as_ref().ok_or("entire selected child plan")?;
 let mut graph=Box::new(Launch{channel:None,job:None});
 let outcome=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||->Result<Value>{
  p.require()?;let endpoint=format!(r"\\.\pipe\Mutiny-RootLaunch-{}-{}",p.recipe.campaign,crate::instance()?);
  graph.channel=Some(Channel::server(endpoint,&p.token.user_sid)?);let c=graph.channel.as_ref().unwrap();
  let mut environment=plan.child_environment.clone();need(environment.insert("MUTINY_ROOT_LAUNCH_PIPE".into(),c.name().into()).is_none(),"source-owned sole RootLaunch route")?;
  graph.job=Some(Job::prepare(&selected.own,&plan.action.arguments,&plan.action.working_directory,&environment,&plan.output_prefix)?);
  let job=graph.job.as_mut().unwrap();p.require()?;job.start_suspended(|_|p.require())?;
  selected.exchange(p,c,job)?;let receipt=job.natural_close()?;p.require()?;
  let mut failures=Vec::new();if let Err(e)=c_close(&mut graph.channel){failures.push(e)}if let Err(e)=job.close_checked(){failures.push(e)}
  need(failures.is_empty(),&format!("native A-to-B independent closures {failures:?}"))?;crate::owned::known()?;Ok(receipt)
 }));
 match outcome{Ok(Ok(v))=>Ok(v),Ok(Err(error))=>{crate::owned::mark_unknown();let _=Box::leak(graph);Err(format!("original A-to-B job/channel UNKNOWN or refused, entire graph retained: {error}"))},Err(payload)=>{crate::owned::mark_unknown();let _=Box::leak(graph);std::mem::forget(payload);Err("original A-to-B invocation unwind; complete graph retained UNKNOWN".into())}}
}
fn c_close(c:&mut Option<Channel>)->Result<()>{if let Some(c)=c.as_mut(){c.close_checked()}else{Ok(())}}
pub(crate) fn anchor(p:&Policy)->Result<Vec<u8>>{p.require()?;let pin=p.own_pin()?;let spec=format!("super::PublicObjectSpec{{path:std::path::PathBuf::from({}),bytes:{},sha256:super::constant_hex::<32>({})?,volume:{},file_id:super::constant_hex::<16>({})?,links:1,owner_sid:super::constant_bytes({})?,dacl_sha256:super::constant_hex::<32>({})?,class:super::PublicClass::OwnTestImage}}",serde_json::to_string(&pin.path).map_err(|e|e.to_string())?,pin.bytes,serde_json::to_string(&pin.sha256).unwrap(),pin.volume,serde_json::to_string(&pin.file_id).unwrap(),serde_json::to_string(&pin.owner_sid_hex).unwrap(),serde_json::to_string(&pin.dacl_sha256).unwrap());let source=format!("//! Generated by reviewed native TEST Root A; one retained monolithic original\n//! truthfully serves issuer image and complete operative native payload roles.\npub(super) fn selected()->super::Result<super::RootLaunchAnchor>{{\n super::RootLaunchAnchor::from_compiled_root({spec},{spec},super::constant_bytes({})?)\n}}\n",serde_json::to_string(&hex::encode(&p.token.user_sid)).unwrap());need(source.len()<=16384,"bounded fresh noncyclic compiled native issuer anchor")?;p.require()?;Ok(source.into_bytes())}
